#include <bits/stdc++.h>
using namespace std;

#define all(x) (x).begin(), (x).end()
#define sz(x) (int)(x).size()

bool solve() {
    int n; cin >> n;
    vector<pair<int, int>> pts(n);
    for (auto &[x, y] : pts)
        cin >> x >> y;
    sort(all(pts));
    vector<int> xs, ys;
    for (auto [x, y] : pts)
        ys.push_back(y);
    sort(all(pts), [](auto a, auto b) { return a.second < b.second; });
    for (auto [x, y] : pts)
        xs.push_back(x);
    // for (int i = 0; i < n; i++)
    //     cout << ys[i] << " ";
    // cout << "\n";
    // for (int i = 0; i < n; i++)
    //     cout << xs[i] << " ";
    // cout << "\n";
    int lo = *min_element(all(xs)), hi = *max_element(all(xs));
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        vector<int> top, bot;
        for (int i = 0; i < n; i++) {
            if (xs[i] >= mid)
                top.push_back(xs[i]);
            else
                bot.push_back(xs[i]);
        }
        bool top_dec = false, bot_dec = false;
        for (int i = 1; i < sz(top); i++)
            if (top[i] < top[i - 1])
                top_dec = true;
        for (int i = 1; i < sz(bot); i++)
            if (bot[i] < bot[i - 1])
                bot_dec = true;
        if (top_dec)
            lo = mid + 1;
        else if (bot_dec)
            hi = mid - 1;
        else
            return true;
    }
    swap(xs, ys);
    lo = *min_element(all(xs)), hi = *max_element(all(xs));
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        vector<int> top, bot;
        for (int i = 0; i < n; i++) {
            if (xs[i] >= mid)
                top.push_back(xs[i]);
            else
                bot.push_back(xs[i]);
        }
        bool top_dec = false, bot_dec = false;
        for (int i = 1; i < sz(top); i++)
            if (top[i] < top[i - 1])
                top_dec = true;
        for (int i = 1; i < sz(bot); i++)
            if (bot[i] < bot[i - 1])
                bot_dec = true;
        if (top_dec)
            lo = mid + 1;
        else if (bot_dec)
            hi = mid - 1;
        else
            return true;
    }
    return false;
}

int main() {
    int t; cin >> t;
    while (t--) {
        cout << (solve() ? "YES" : "NO") << "\n";
    }
}
